package com.asmj.marketplace.vendor.controller; import com.asmj.marketplace.vendor.model.Vendor;import com.asmj.marketplace.vendor.service.VendorService;import com.asmj.marketplace.common.response.ApiResponse;import lombok.RequiredArgsConstructor;import org.springframework.security.core.Authentication;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*; @RestController @RequestMapping("/api/vendors") @RequiredArgsConstructor public class VendorController {private final VendorService s;@PostMapping @PreAuthorize("hasAnyRole('USER','VENDOR')") public ApiResponse<Vendor> create(Authentication a,@RequestBody Vendor v){return ApiResponse.ok("Vendor submitted for approval",s.create(a.getName(),v));}@GetMapping("/me") @PreAuthorize("hasRole('VENDOR')") public ApiResponse<Vendor> me(Authentication a){return ApiResponse.ok("Vendor",s.me(a.getName()));}@PutMapping("/me") @PreAuthorize("hasRole('VENDOR')") public ApiResponse<Vendor> updateMe(Authentication a,@RequestBody Vendor v){return ApiResponse.ok("Vendor updated",s.update(a.getName(),v));}@GetMapping("/{id}") public ApiResponse<Vendor> get(@PathVariable String id){return ApiResponse.ok("Vendor",s.get(id));}@GetMapping("/enquiries") @PreAuthorize("hasRole('VENDOR')") public ApiResponse<List<com.asmj.marketplace.enquiry.model.Enquiry>> enquiries(Authentication a){return ApiResponse.ok("Vendor enquiries",s.enquiries(a.getName()));}@GetMapping public ApiResponse<List<Vendor>> all(){return ApiResponse.ok("Vendors",s.all());}}
